import javax.tools.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.net.*;
import java.util.*;

/** Executes shipping shutter/accept/completion handlers with a deliberately stalled save executor. */
public final class CaptureWorkflowRegression {
    static String method(String source,String name){int start=source.indexOf(name),body=source.indexOf('{',start),depth=0;if(start<0)throw new AssertionError(name);for(int i=body;i<source.length();i++){if(source.charAt(i)=='{')depth++;if(source.charAt(i)=='}'&&--depth==0)return source.substring(start,i+1);}throw new AssertionError(name);}
    public static void main(String[] args)throws Exception{
        Path root=Paths.get(args[0]),dir=root.resolve("build/capture-workflow-tests"),classes=dir.resolve("classes");Files.createDirectories(classes);
        String activity=new String(Files.readAllBytes(root.resolve("src/com/silverroom/camera/MainActivity.java")),StandardCharsets.UTF_8);
        String methods="";for(String name:new String[]{"void capture()","void tick(int n,long token)","void resetShutter()","public void picture(CameraEngine.Shot shot)","void captureSaved(String id,String extra)","String reservePhotoId(long when)","List<String> negativeIds()"})methods+=method(activity,name);
        Path fixture=dir.resolve("CaptureProbe.java");Files.write(fixture,(prefix()+methods+probe()).getBytes(StandardCharsets.UTF_8));
        String cp=root.resolve("build/test-classes").toString();
        if(ToolProvider.getSystemJavaCompiler().run(null,null,null,"--release","8","-encoding","UTF-8","-cp",cp,"-d",classes.toString(),fixture.toString(),root.resolve("src/com/silverroom/camera/CaptureQueue.java").toString())!=0)throw new AssertionError("Capture workflow fixture compile failed");
        try(URLClassLoader loader=new URLClassLoader(new URL[]{classes.toUri().toURL()})){try{List<?> results=(List<?>)loader.loadClass("com.silverroom.camera.CaptureProbe").getMethod("run",String.class).invoke(null,dir.toString());for(Object item:results)System.out.println("PASS "+item);System.out.println("ALL "+results.size()+" BACKGROUND CAPTURE CHECKS PASSED");}catch(java.lang.reflect.InvocationTargetException e){throw new AssertionError("Capture workflow",e.getCause());}}
    }
    static String prefix(){return
        "package com.silverroom.camera;import java.util.*;import java.util.concurrent.*;import java.io.*;import java.text.SimpleDateFormat;public class CaptureProbe {"+
        "static List<String> passed=new ArrayList<>();static void check(boolean yes,String name){if(!yes)throw new AssertionError(name);passed.add(name);}final CaptureQueue captures=new CaptureQueue();long captureToken;boolean busy,exporting,destroyed;int page,shots,timer,frameFormat,refreshes,galleryRefreshes;String latest,writingPhotoId;File rollDir;Film.Settings settings=new Film.Settings();Widget finder=new Widget(),filmGroupButton=new Widget(),filmWheel=new Widget(),lensWheel=new Widget(),shutter=new Widget(),countdown=new Widget(),frameCount=new Widget();Touch finderTouch=new Touch();Handler main=new Handler();Exec worker=new Exec();Prefs prefs=new Prefs();Updates updates=new Updates();CameraEngine camera=new CameraEngine();List<String> messages=new ArrayList<>();"+
        "static class Manifest{static class permission{static String CAMERA=\"camera\";}}static class PackageManager{static int PERMISSION_GRANTED=0;}static class HapticFeedbackConstants{static int VIRTUAL_KEY=0;}int checkSelfPermission(String p){return 0;}void requestPermissions(String[] p,int n){}Film.Settings liveSettings(){return settings.copy();}void toast(String s){messages.add(s);}void refreshLensButtons(){refreshes++;}void updateLatest(String id){latest=id;}void refreshGallery(){galleryRefreshes++;}"+
        "static class Widget{boolean busy,enabled=true,layout;String text=\"\";int getWidth(){return 720;}int getHeight(){return 960;}boolean isLayoutRequested(){return layout;}void setEnabled(boolean b){enabled=b;}void invalidate(){}void setText(String t){text=t;}void setTextSize(int n){}void finish(){}void performHapticFeedback(int n){}}static class Touch{void cancel(){}}"+
        "static class Handler{List<Runnable> now=new ArrayList<>(),later=new ArrayList<>();void post(Runnable r){now.add(r);}void postDelayed(Runnable r,long ms){later.add(r);}void flush(){while(!now.isEmpty()){List<Runnable> copy=new ArrayList<>(now);now.clear();for(Runnable r:copy)r.run();}}void timeout(){List<Runnable> copy=new ArrayList<>(later);later.clear();for(Runnable r:copy)r.run();}}"+
        "static class Exec{List<Runnable> tasks=new ArrayList<>();boolean rejected;void execute(Runnable r){if(rejected)throw new RejectedExecutionException();tasks.add(r);}void next(){tasks.remove(0).run();}}static class Updates{int flushes;void flush(){flushes++;}}static class Prefs{int shots;boolean getBoolean(String k,boolean d){return d;}int getInt(String k,int d){return shots;}Prefs edit(){return this;}Prefs putInt(String k,int n){shots=n;return this;}void apply(){}}"+
        "static class CameraEngine{boolean pending;int shoots;long ticket;boolean focalPending(){return pending;}void shoot(long n){shoots++;ticket=n;}static class Info{int iso=400;}static class Shot{long ticket;Info info=new Info();String lens=\"85mm\";File dng;CaptureOrientation.Snapshot orientation=new CaptureOrientation.Snapshot(90,90,false);Shot(long n){ticket=n;}}}"+
        "List<Film.Settings> developed=new ArrayList<>();List<Float> aspects=new ArrayList<>();void developCapture(CameraEngine.Shot shot,CaptureQueue.Ticket job,Film.Settings film,float aspect,String lens){developed.add(film);aspects.add(aspect);captures.finish(job.token);main.post(()->captureSaved(\"saved-\"+job.token,\"\"));}";
    }
    static String probe(){return
        "public static List<String> run(String directory)throws Exception{"+
        "CaptureProbe a=new CaptureProbe();a.settings.stock=3;a.settings.strength=.7f;a.capture();long first=a.captureToken;check(a.busy&&a.camera.shoots==1&&a.captures.count()==1,\"A shutter reserves one bounded slot before requesting sensor output\");a.settings.stock=12;a.settings.strength=.2f;a.frameFormat=3;a.picture(new CameraEngine.Shot(first));check(a.busy&&a.worker.tasks.size()==1,\"JPEG receipt queues expensive work without running it on the callback thread\");a.main.flush();check(!a.busy&&!a.shutter.busy&&a.filmWheel.enabled&&a.countdown.text.isEmpty()&&a.worker.tasks.size()==1,\"Accepted photo releases the shutter while development remains deliberately stalled and no processing label appears\");"+
        "a.capture();long second=a.captureToken;check(a.busy&&a.camera.shoots==2&&a.captures.count()==2,\"A second shutter is allowed while the first photo is still waiting for development\");a.worker.next();a.main.flush();check(a.busy&&a.captureToken==second&&a.shutter.busy&&a.latest.equals(\"saved-\"+first)&&a.messages.isEmpty(),\"Completing the older photo updates the thumbnail silently without resetting the newer shutter\");check(a.developed.get(0).stock==3&&a.developed.get(0).strength==.7f&&a.developed.get(0).iso==400&&Math.abs(a.aspects.get(0)-4f/3)<.001f,\"The queued photo preserves its own film, strength, ISO and landscape framing instead of current camera controls\");"+
        "a.picture(new CameraEngine.Shot(second));a.main.flush();a.worker.next();a.main.flush();check(a.developed.get(1).stock==12&&a.developed.get(1).strength==.2f&&a.aspects.get(1)==1&&a.prefs.shots==2,\"Consecutive photos keep separate recipe/frame snapshots and increment the saved counter once each\");int tasks=a.worker.tasks.size();a.picture(new CameraEngine.Shot(second));check(a.worker.tasks.size()==tasks&&a.prefs.shots==2,\"A duplicate completed JPEG cannot enqueue or count a second photo\");"+
        "a=new CaptureProbe();for(int i=0;i<CaptureQueue.LIMIT;i++){a.capture();a.picture(new CameraEngine.Shot(a.captureToken));a.main.flush();}int shoots=a.camera.shoots;a.capture();check(a.camera.shoots==shoots&&!a.busy&&a.captures.count()==4&&a.messages.size()==1,\"Four pending photos bound compressed-image memory; a full queue never requests an unreserved fifth capture\");a.worker.next();a.main.flush();a.capture();check(a.camera.shoots==shoots+1&&a.busy,\"One completed save immediately frees a slot for another shutter\");"+
        "CaptureQueue q=new CaptureQueue();Film.Settings original=new Film.Settings();original.stock=4;CaptureQueue.Ticket t=q.reserve(1,original,new FrameFormat.Snapshot(1,300,400));original.stock=9;Film.Settings copy=t.settings();copy.stock=15;check(t.settings().stock==4,\"Reservation and returned settings are defensive copies\");check(q.reserve(1,original,t.frame)==null&&q.count()==1,\"Duplicate reservation tokens cannot replace a queued recipe\");q.accept(1);q.cancel(1);check(q.count()==1&&q.accept(1)==null,\"UI cancellation and duplicate receipt cannot discard an already accepted photo\");q.finish(1);q.finish(1);check(q.count()==0,\"Repeated completion releases a photo slot exactly once\");q.reserve(2,original,t.frame);q.cancel(2);check(q.accept(2)==null&&q.count()==0,\"Cancelled not-yet-received captures reject stale callbacks\");"+
        "a=new CaptureProbe();a.capture();first=a.captureToken;a.resetShutter();a.capture();second=a.captureToken;List<Runnable> oldTimeout=new ArrayList<>(a.main.later.subList(0,1));for(Runnable r:oldTimeout)r.run();check(a.busy&&a.captureToken==second&&a.captures.count()==1,\"An older shutter timeout cannot unlock or cancel the next photo\");a.camera.pending=true;a.resetShutter();shoots=a.camera.shoots;a.capture();check(a.camera.shoots==shoots&&a.captures.count()==0,\"Real preview readiness remains mandatory between split-output captures\");"+
        "a=new CaptureProbe();a.capture();a.worker.rejected=true;a.picture(new CameraEngine.Shot(a.captureToken));a.main.flush();check(!a.busy&&a.captures.count()==0&&a.messages.size()==1,\"A rejected background executor releases its slot and reports failure without leaving a stuck shutter\");"+
        "a=new CaptureProbe();a.capture();first=a.captureToken;a.resetShutter();File raw=File.createTempFile(\"stale-\",\".dng\",new File(directory));CameraEngine.Shot stale=new CameraEngine.Shot(first);stale.dng=raw;a.picture(stale);check(!raw.exists()&&a.worker.tasks.isEmpty(),\"A stale cancelled shot cleans its RAW temp file and never creates a phantom thumbnail\");"+
        "a=new CaptureProbe();a.page=2;a.captureSaved(\"gallery\",\"\");check(a.galleryRefreshes==1&&a.latest.equals(\"gallery\")&&a.messages.isEmpty(),\"A completed background save also refreshes an open negative list without a success toast\");a.destroyed=true;a.captureSaved(\"after-destroy\",\"\");check(a.prefs.shots==2&&a.latest.equals(\"gallery\"),\"Finishing an accepted save after activity destruction persists the count without touching dead UI\");"+
        "a=new CaptureProbe();a.rollDir=new File(directory,\"ids-\"+System.nanoTime());a.rollDir.mkdir();String x=a.reservePhotoId(1234567890000L),y=a.reservePhotoId(1234567890000L);check(!x.equals(y)&&NegativeStore.valid(x)&&NegativeStore.valid(y),\"Photos sharing a shutter millisecond reserve distinct original files without overwriting\");new File(a.rollDir,x+\".json\").createNewFile();new File(a.rollDir,y+\".json\").createNewFile();a.writingPhotoId=y;check(a.negativeIds().equals(Collections.singletonList(x)),\"Unfinished metadata is hidden from the thumbnail/gallery/detail selection lists\");a.writingPhotoId=null;check(a.negativeIds().size()==2,\"Only completed saves become visible to the negative browser\");return passed;}}";
    }
}
